CREATE TABLE access_identity (id uuid PRIMARY KEY, login_normalized varchar(254) NOT NULL UNIQUE, display_name varchar(200) NOT NULL, identity_type varchar(20) NOT NULL CHECK (identity_type IN ('HUMAN','TECHNICAL')), active boolean NOT NULL DEFAULT true, revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0), created_at timestamptz NOT NULL, deactivated_at timestamptz);
CREATE TABLE access_credential (id uuid PRIMARY KEY, identity_id uuid NOT NULL UNIQUE REFERENCES access_identity(id) ON DELETE RESTRICT, bcrypt_hash varchar(100) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL, rotated_at timestamptz);
CREATE TABLE access_session (id uuid PRIMARY KEY, identity_id uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'), csrf_token_hash char(64) NOT NULL CHECK (csrf_token_hash ~ '^[0-9a-f]{64}$'), created_at timestamptz NOT NULL, last_activity_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, CHECK (created_at <= last_activity_at AND last_activity_at <= expires_at));
CREATE INDEX ix_access_session_identity_active ON access_session(identity_id, revoked_at, expires_at);
CREATE TABLE authentication_attempt (id uuid PRIMARY KEY, subject_key char(64) NOT NULL, source_key char(64) NOT NULL, occurred_at timestamptz NOT NULL, success boolean NOT NULL, correlation_id uuid NOT NULL);
CREATE INDEX ix_auth_attempt_subject_date ON authentication_attempt(subject_key, occurred_at DESC);
CREATE TABLE institutional_actor (id uuid PRIMARY KEY, identity_id uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, actor_type varchar(100) NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, CHECK (valid_from < valid_to));
CREATE TABLE process_function (id uuid PRIMARY KEY, code varchar(100) NOT NULL UNIQUE, name varchar(200) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE function_operation (function_id uuid NOT NULL REFERENCES process_function(id) ON DELETE RESTRICT, operation_code varchar(150) NOT NULL, PRIMARY KEY(function_id, operation_code));
CREATE TABLE technical_privilege (id uuid PRIMARY KEY, identity_id uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, privilege_code varchar(150) NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, CHECK (valid_from < valid_to));
CREATE TABLE functional_assignment (id uuid PRIMARY KEY, identity_id uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, function_id uuid NOT NULL REFERENCES process_function(id) ON DELETE RESTRICT, career_id uuid NOT NULL, process_id uuid, indicator_id uuid, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, granted_by uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, granted_at timestamptz NOT NULL, revoked_at timestamptz, revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0), CHECK (valid_from < valid_to), CHECK (indicator_id IS NULL OR process_id IS NOT NULL));
CREATE INDEX ix_assignment_identity_vigency ON functional_assignment(identity_id, valid_from, valid_to, revoked_at);
CREATE INDEX ix_assignment_scope ON functional_assignment(career_id, process_id, indicator_id);
CREATE TABLE conflict_policy (id uuid PRIMARY KEY, left_function_id uuid NOT NULL REFERENCES process_function(id) ON DELETE RESTRICT, right_function_id uuid NOT NULL REFERENCES process_function(id) ON DELETE RESTRICT, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, CHECK (left_function_id <> right_function_id), CHECK (valid_from < valid_to), UNIQUE(left_function_id, right_function_id, valid_from));
CREATE TABLE conflict_exception (id uuid PRIMARY KEY, policy_id uuid NOT NULL REFERENCES conflict_policy(id) ON DELETE RESTRICT, identity_id uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, career_id uuid NOT NULL, process_id uuid, indicator_id uuid, justification varchar(2000) NOT NULL CHECK (char_length(trim(justification)) BETWEEN 10 AND 2000), valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, approved_by uuid NOT NULL REFERENCES access_identity(id) ON DELETE RESTRICT, revoked_at timestamptz, CHECK (valid_from < valid_to), CHECK (indicator_id IS NULL OR process_id IS NOT NULL));
CREATE INDEX ix_conflict_exception_identity_vigency ON conflict_exception(identity_id, valid_from, valid_to, revoked_at);
CREATE INDEX ix_function_operation_code ON function_operation(operation_code);
CREATE INDEX ix_conflict_policy_pair ON conflict_policy(left_function_id, right_function_id);
CREATE INDEX ix_assignment_function_vigency ON functional_assignment(function_id, valid_from, valid_to, revoked_at);
REVOKE DELETE ON access_identity, functional_assignment, conflict_policy, conflict_exception FROM PUBLIC;
